mapper.select:
SELECT id, user_id, song_id, mission_id, parent_session_id, score_version, bpm, bpm_unit, idempotency_key, request_hash, start_note_idx, end_note_idx, recording_url, recording_bytes, recording_duration_ms, recording_sample_rate, recording_channels, status, fail_reason, analysis_attempt, analysis_started_at, started_at, ended_at, saved_at, memo, viewed_at, record_deleted_at, created_at
FROM practice_sessions
WHERE id = #{id}

mapper.update:
UPDATE practice_sessions
SET status = 'FAILED', fail_reason = #{failReason}
WHERE status = 'RECORDING' AND started_at < #{cutoff}

mapper.select:
SELECT status, fail_reason, started_at
FROM practice_sessions
WHERE id = #{sessionId} AND user_id = #{userId}
